use std :: { fmt , io } ; use colored :: Colorize ; use forge_tracker :: VERSION ; # [doc = " Displays the banner with version and command tips."] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `cli_mode` - If true, shows CLI-relevant commands. Both interactive and"] # [doc = "   CLI modes use `:` as the canonical command prefix."] # [doc = ""] # [doc = " # Environment Variables"] # [doc = ""] # [doc = " * `FORGE_BANNER` - Optional custom banner text to display instead of the"] # [doc = "   default"] pub fn display (cli_mode : bool) -> io :: Result < () > { let mut banner = std :: env :: var ("FORGE_BANNER") . ok () . filter (| s | ! s . is_empty ()) . unwrap_or_else (| | BANNER . to_string ()) ; let version_label = ("Version:" , VERSION) ; let tips : Vec < (& str , & str) > = if cli_mode { vec ! [("New conversation:" , ":new") , ("Get started:" , ":info, :conversation") , ("Switch model:" , ":model") , ("Switch provider:" , ":provider") , ("Switch agent:" , ":<agent_name> e.g. :forge or :muse") ,] } else { vec ! [("New conversation:" , ":new") , ("Get started:" , ":info, :usage, :help, :conversation") , ("Switch model:" , ":model") , ("Switch agent:" , ":forge or :muse or :agent") , ("Update:" , ":update") , ("Quit:" , ":exit or <CTRL+D>") ,] } ; let labels : Vec < (& str , & str) > = std :: iter :: once (version_label) . chain (tips) . collect () ; let max_width = labels . iter () . map (| (key , _) | key . len ()) . max () . unwrap_or (0) ; for (key , value) in & labels { banner . push_str (format ! ("\n{}{}" , format ! ("{key:>max_width$} ") . dimmed () , value . cyan ()) . as_str () ,) ; } println ! ("{banner}\n") ; if ! cli_mode { display_zsh_encouragement () ; } Ok (()) }